import { ProductCard } from "./components/ProductCard";
import { products } from "./lib/products";

export default function App() {
  return (
    <main>
      <Card title="Picked for you">
        <ProductCard product={products[0]} size="sm" />
      </Card>
      <Card title="Members save 10%">
        <p>Log in to see member prices.</p>
        <a href="/login">Log in</a>
      </Card>
    </main>
  );
}

import type { ReactNode } from "react";

type PageLayoutProps = {
  header: ReactNode;
  sidebar: ReactNode;
  children: ReactNode;
};

export function PageLayout({ header, sidebar, children }: PageLayoutProps) {
  return (
    <div className="page">
      <header className="page-header">{header}</header>
      <aside className="page-sidebar">{sidebar}</aside>
      <main className="page-main">{children}</main>
      <footer className="page-footer">Trailhead Outfitters</footer>
    </div>
  );
}

steps.body:
Real screens change with their data. A sold-out product says so, an empty cart says it's empty, and the header shows a Log in link or the name of whoever is logged in. With hand-written DOM code you'd add and remove elements as things change. In React you describe what the screen shows in each case, and React adds and removes the elements for you. It takes nothing new, only ordinary JavaScript in a few patterns you'll use every day.

## An early return

A component is a function, so it can use `if` before its `return` and return something else when a condition holds:

```tsx sketch
export function ProductGrid({ products }: ProductGridProps) {
  if (products.length === 0) {
    return <p>No products match your filters.</p>;
  }
  return <div className="grid">...</div>;
}
```

This is the clearest way to handle a whole different screen, like one that's empty, still loading, or failed.

## The conditional operator

Inside JSX, braces take only expressions, so `if` can't go there. The **conditional operator** can: `condition ? a : b` gives `a` when the condition is true and `b` when it's false. It's also called the **ternary**, since it takes three pieces.

```tsx
<p>{product.inStock ? formatPrice(product.priceCents) : "Sold out"}</p>
```

## The and operator

For something or nothing, use `&&`. `a && b` gives `a` when `a` is falsy, and `b` otherwise. A **falsy** value is one JavaScript treats as false: `false`, `0`, an empty string, `null`, `undefined`, and `NaN` (not a number). React shows nothing for `false`, `null`, and `undefined`, so this paragraph appears only when the product is sold out:

```tsx
{!product.inStock && <p className="muted">Back soon</p>}
```

## The zero trap

React shows nothing for `false`, but it does show numbers, and `0` is a number. So `{count && <span>{count}</span>}` shows a stray 0 when `count` is zero, since `0 && anything` is `0`. The second example shows it happening. The fix is to put a real true or false on the left, like `count > 0 && ...`.

## Returning null

A component can return `null` to show nothing at all. A banner that only appears during a sale can decide for itself, so the pages that use it don't have to:

```tsx
export function SaleBanner({ percentOff }: SaleBannerProps) {
  if (percentOff === 0) {
    return null;
  }
  return <p className="banner">{percentOff}% off everything this weekend</p>;
}
```

## Left out, or hidden?

There are two ways to make something disappear, and they aren't the same.

- **Left out of the JSX**, with any of the patterns above, it has no DOM nodes at all. If it was a component, React forgets everything it was keeping track of, like what someone typed into it, and it starts fresh if it comes back.
- **Hidden with CSS**, like the `hidden` attribute or `display: none`, it stays in the DOM, out of sight, with everything kept. The browser still skips drawing it, as the web course showed.

Leaving it out is usually right: less in the DOM, and nothing stale. Hiding fits something that comes back often and should come back as it was, like a tab with a half-written review in it. What a component keeps track of is called **state**, and the State and Events lesson covers it. The Re-rendering and Performance lesson shows exactly when React keeps it and when it throws it away.

examples.code:
import { formatPrice } from "../lib/format";
import type { Product } from "../lib/products";

type StockCardProps = {
  product: Product;
};

export function StockCard({ product }: StockCardProps) {
  return (
    <article className="card">
      <h3>{product.name}</h3>
      <p>{product.inStock ? formatPrice(product.priceCents) : "Sold out"}</p>
      {!product.inStock && (
        <a href={`/products/${product.slug}/notify`}>Email me when it's back</a>
      )}
    </article>
  );
}

type CartLinkProps = {
  count: number;
};

export function CartLink({ count }: CartLinkProps) {
  return (
    <a href="/cart">
      Cart
      {count && <span className="badge">{count}</span>}
    </a>
  );
}

import { formatPrice } from "../lib/format";
import type { Product } from "../lib/products";

type ProductListProps = {
  products: Product[];
};

export function ProductList({ products }: ProductListProps) {
  const shown = products
    .filter((product) => product.inStock)
    .toSorted((a, b) => a.priceCents - b.priceCents);

  return (
    <ul>
      {shown.map((product) => (
        <li key={product.slug}>
          {product.name}, {formatPrice(product.priceCents)}
        </li>
      ))}
    </ul>
  );
}

import type { Product } from "../lib/products";

type NoKeyListProps = {
  products: Product[];
};

export function NoKeyList({ products }: NoKeyListProps) {
  return (
    <ul>
      {products.map((product) => (
        <li>{product.name}</li>
      ))}
    </ul>
  );
}

import { clsx } from "clsx";
import { formatPrice } from "../lib/format";
import type { Product } from "../lib/products";

type ProductCardProps = {
  product: Product;
  size?: "sm" | "md";
};

const sizes = {
  sm: "p-3 text-sm",
  md: "p-5 text-base",
};

export function ProductCard({ product, size = "md" }: ProductCardProps) {
  return (
    <article
      className={clsx(
        "rounded-lg border border-stone-200 bg-white shadow-sm",
        sizes[size],
        !product.inStock && "opacity-60",
      )}
    >
      <h3 className="font-semibold text-stone-900">{product.name}</h3>
      <p className="text-stone-600">{formatPrice(product.priceCents)}</p>
    </article>
  );
}

import { clsx } from "clsx";
import type { ReactNode } from "react";
import styles from "./Badge.module.css";

type BadgeProps = {
  tone?: "plain" | "sale";
  children: ReactNode;
};

export function Badge({ tone = "plain", children }: BadgeProps) {
  return (
    <span className={clsx(styles.badge, tone === "sale" && styles.sale)}>
      {children}
    </span>
  );
}

type RatingBarProps = {
  average: number;
};

export function RatingBar({ average }: RatingBarProps) {
  const percent = (average / 5) * 100;

  return (
    <div
      className="h-2 w-24 rounded-full bg-stone-200"
      role="img"
      aria-label={`Rated ${average} out of 5`}
    >
      <div className="h-full rounded-full bg-amber-500" style={{ width: `${percent}%` }} />
    </div>
  );
}
